command:
$vscode = Get-Process -Name 'Code' -ErrorAction SilentlyContinue
if ($vscode) {
  $codePath = (Get-Command code -ErrorAction SilentlyContinue)?.Source
  if (-not $codePath) { $codePath = "$env:LOCALAPPDATA\Programs\Microsoft VS Code\bin\code.cmd" }
  & $codePath --disable-extension GitHub.copilot 2>&1 | Write-Host
  & $codePath --disable-extension GitHub.copilot-chat 2>&1 | Write-Host
  Write-Host 'Copilot extension disabled (takes effect on next VS Code window)'
} else {
  Write-Host 'VS Code not running — skipping (extension will be disabled on next open)'
  $codePath = "$env:LOCALAPPDATA\Programs\Microsoft VS Code\bin\code.cmd"
  if (Test-Path $codePath) {
    & $codePath --disable-extension GitHub.copilot 2>&1 | Write-Host
    & $codePath --disable-extension GitHub.copilot-chat 2>&1 | Write-Host
    Write-Host 'Disabled via CLI even though VS Code window was not open'
  }
}
Write-Host 'done'
